-- Import des courriers arrivées 2014
-- Source : 2014.xlsx (feuille 2014).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N° ARRIVEE                  -> txt_numdordre (00001/jj-mm-aaaa)
--   N.DOSSIER                   -> txt_numdossier
--   DATE CREATION               -> dt_datearrivee
--   N° ET DATE CORRESPONDANCES  -> txt_reference, txt_numcourier, dt_datecourier
--   PRENOMS + NOMS              -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS                -> txt_objet (libellé d'origine)
--   DESIGNATIONS                -> txt_designation (liste designationsParCategorie)
--   designation retenue         -> txt_categorie
--   NGA                         -> txt_numTitreFoncier
--   ANCIEN TITRE FONCIER        -> txt_numTitreMere
--   N° LOT                      -> txt_numLot
--   SITUATION                   -> txt_lotissement
--   N° BE                       -> txt_numbordereau
--   AGENTS TRAITEUR             -> txt_agenttraiteur
--   OBSERVATIONS                -> txt_observation
--   DATE DEPART                 -> ajoutée à txt_observation si présente
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si la désignation commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Référence absente : « <N° arrivée> du jj-mm-aaaa ».
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates d'arrivée illisibles reconstituées sur la ligne voisine : 4
-- Lignes importées : 2456
-- Lignes non importées :
--   ligne Excel 2041 : N° 1920 sans objet, nom ni référence
--
-- Répartition des catégories :
--    2318  Demande SERVICES
--      76  Information
--      57  Convocation - Invitation
--       3  Réclamation - Signalement
--       2  Réquisition - Instruction
-- Désignations :
--    1124  Morcellements
--     497  Demande de Régularisation par voie de Bail
--     304  Demande de Cession définitive
--      82  Demande d'états des lieux
--      71  Demande de délimitation
--      62  Autorisation de construction
--      56  Demande de terrain/Echange
--      42  Réunion
--      23  Duplication de CIC
--      20  Réquisition d'immatriculation
--      19  Demande d'évaluation
--      15  Demande de situation foncière
--      14  Rapport
--      13  Autres
--      13  Décision - Arrêté
--      13  Note de service
--      11  Autorisation de lotir
--       8  PV - Compte - rendu
--       8  Formation
--       8  Demande de CIC
--       7  Transmission lettre
--       7  Tribunal
--       6  Demande d'extraits de plan
--       5  Document administratif
--       4  Litiges
--       3  Demande d'attestation du Cadastre
--       3  Atelier
--       3  Visite de site
--       3  Réceptions de lotissements
--       3  Plainte
--       3  Demande de Titre foncier
--       2  Circulaire
--       2  Instruction à suivre
--       1  Lettre
--       1  Cérémonie

SET NAMES utf8mb4;

START TRANSACTION;








COMMIT;
